INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '一定の速さで直線上を動く物体の運動を何というか。', NULL, '["等加速度運動","等速円運動","等速直線運動","自由落下運動","単振動"]', 2, '["速さも向きも変わらない直線運動を等速直線運動という。加速度は常に0である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, 'てこにおいて、力点・支点・作用点の位置関係のうち、小さな力で大きな力を得られる条件として正しいものはどれか。', NULL, '["支点から力点までの距離を短くする","支点から力点までの距離を長くする","支点から作用点までの距離を長くする","力点と作用点を同じ位置にする","支点を作用点に近づけない"]', 1, '["てこでは「力点での力×支点からの距離=作用点での力×支点からの距離」の関係が成り立つため、支点から力点までの距離を長くするほど、小さな力で大きな作用力を生み出せる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '電流が磁界から受ける力を利用した装置はどれか。', NULL, '["発電機","モーター","変圧器","コンデンサー","抵抗器"]', 1, '["モーターは電流が磁界の中で受ける力(フレミングの左手の法則)を利用して回転運動を生み出す装置である。発電機はこの逆で、運動から電流を得る装置。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '音の高さを決める要素はどれか。', NULL, '["振幅","振動数","波の速さ","音圧","波長のみで振動数と無関係に決まる"]', 1, '["音の高さ(音程)は振動数(周波数)によって決まる。振動数が多いほど高い音になる。振幅は音の大きさを決める。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '凸レンズによってできる実像の説明として正しいものはどれか。', NULL, '["物体と同じ側にできる、上下左右が同じ向きの像","物体と反対側にスクリーンに映せる、上下左右が逆転した像","虚像と同じで、レンズを通して見える拡大された像","必ず物体より小さくなる像","光が実際に集まらずにできる見かけの像"]', 1, '["凸レンズで物体が焦点の外側にあるとき、レンズの反対側に光が実際に集まってできる像を実像といい、上下左右が逆転してスクリーンに映すことができる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '物体が水に浮くか沈むかを決める最も基本的な要因はどれか。', NULL, '["物体の色","物体の密度と水の密度の大小関係","物体の温度","物体の表面積のみ","物体の電気的な性質"]', 1, '["物体の密度が水の密度より小さければ浮き、大きければ沈む。これはアルキメデスの原理(浮力)に基づく。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '静止していた物体に一定の力を加え続けたとき起こることとして正しいものはどれか。', NULL, '["速さは変化せず向きだけ変わる","一定の速さで動き続ける","加速度が生じ、速さが増していく","物体は動かない","力を加えるほど質量が増える"]', 2, '["ニュートンの運動の第2法則(F=ma)により、力を加え続けると物体には加速度が生じ、速さが時間とともに増加していく。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '熱の伝わり方のうち、物質そのものが移動して熱を運ぶものはどれか。', NULL, '["伝導","対流","放射","反射","屈折"]', 1, '["対流は、温められた液体や気体そのものが移動することで熱が運ばれる現象。伝導は物質内を熱が伝わる現象、放射は電磁波として熱が伝わる現象。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '電気抵抗の単位として正しいものはどれか。', NULL, '["ボルト(V)","アンペア(A)","オーム(Ω)","ワット(W)","ジュール(J)"]', 2, '["電気抵抗の単位はオーム(Ω)である。ボルトは電圧、アンペアは電流、ワットは電力、ジュールはエネルギー(仕事)の単位。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, 'ばねばかりで測定される「ばねの伸び」と「加えた力」の関係を表す法則はどれか。', NULL, '["オームの法則","フックの法則","パスカルの法則","万有引力の法則","慣性の法則"]', 1, '["ばねの伸びは、ある範囲内では加えた力の大きさに比例する。これをフックの法則という。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・物理）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '物質が酸素と結びつく化学変化を何というか。', NULL, '["還元","中和","酸化","電離","蒸発"]', 2, '["物質が酸素と結びつく化学反応を酸化という。逆に酸素を失う反応を還元という。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '次のうち、混合物はどれか。', NULL, '["酸素","塩化ナトリウム","水","空気","鉄"]', 3, '["空気は窒素・酸素・二酸化炭素などが混ざり合った混合物である。酸素、塩化ナトリウム、水、鉄はいずれも単一の物質(純物質)。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '酸性の水溶液にBTB溶液を加えたときの色として正しいものはどれか。', NULL, '["青色","緑色","黄色","赤色","無色"]', 2, '["BTB溶液は酸性で黄色、中性で緑色、アルカリ性で青色を示す。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '原子核を構成する粒子の組み合わせとして正しいものはどれか。', NULL, '["陽子と電子","陽子と中性子","電子と中性子","陽子のみ","電子のみ"]', 1, '["原子核は陽子と中性子から構成される。電子は原子核の周りを取り巻くように存在する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '食塩水から水を蒸発させて食塩の結晶を取り出す操作を何というか。', NULL, '["ろ過","蒸留","再結晶","抽出","中和"]', 2, '["溶液を加熱して溶媒を蒸発させ、溶質の結晶を析出させる操作を再結晶という(この場合は蒸発による濃縮・結晶化)。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '気体を集める方法のうち、水に溶けやすく空気より軽い気体を集めるのに適した方法はどれか。', NULL, '["水上置換法","上方置換法","下方置換法","常温放置法","加熱蒸発法"]', 1, '["水に溶けやすく空気より軽い気体(アンモニアなど)は、容器の上方に気体がたまるように集める上方置換法が適している。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '化学反応式 2H2 + O2 → 2H2O が表す反応として正しいものはどれか。', NULL, '["水の電気分解","水素の燃焼","中和反応","酸化銀の分解","炭酸水素ナトリウムの分解"]', 1, '["水素と酸素が結びついて水ができる反応であり、これは水素が酸素と反応して燃える「水素の燃焼」を表す。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '酸とアルカリが反応して互いの性質を打ち消し合う反応を何というか。', NULL, '["酸化","還元","中和","電離","昇華"]', 2, '["酸とアルカリが反応して塩と水ができ、互いの性質を打ち消し合う反応を中和という。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '金属に共通する性質として誤っているものはどれか。', NULL, '["電気を通しやすい","熱を伝えやすい","たたくと薄く広がる(展性)","みがくと特有の光沢が出る","すべて常温で気体である"]', 4, '["金属は常温で多くが固体である(水銀は例外的に液体だが、気体の金属は常温では存在しない)。電気伝導性・熱伝導性・展性・光沢は金属に共通する性質。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '周期表において、性質のよく似た元素が並ぶ縦の列を何というか。', NULL, '["周期","族","同素体","同位体","価数"]', 1, '["周期表の縦の列を族といい、同じ族の元素は最外殻電子の数が似ているため、化学的性質もよく似る。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・化学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, 'ヒトの消化液のうち、タンパク質を分解する酵素を含むものはどれか。', NULL, '["だ液","胃液","胆汁","涙","汗"]', 1, '["胃液に含まれるペプシンという酵素はタンパク質を分解する。だ液にはデンプンを分解するアミラーゼが含まれる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '植物の細胞にあり、動物の細胞には見られない構造はどれか。', NULL, '["核","細胞膜","細胞壁","ミトコンドリア","細胞質"]', 2, '["細胞壁は植物細胞に特有の構造で、細胞の形を保ち植物体を支える役割がある。動物細胞には存在しない。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, 'ヒトの血液の成分のうち、酸素を運搬する働きをもつものはどれか。', NULL, '["血小板","白血球","赤血球","血しょう","リンパ球"]', 2, '["赤血球に含まれるヘモグロビンが酸素と結合し、全身に酸素を運搬する。白血球は免疫、血小板は血液凝固に関わる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '生物が外界の刺激に反応して体の働きを一定に保とうとする性質を何というか。', NULL, '["適応","恒常性(ホメオスタシス)","進化","遺伝","変異"]', 1, '["体温や血糖値などを一定範囲に保とうとする働きを恒常性(ホメオスタシス)という。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, 'メンデルの遺伝の法則のうち、対立形質が親から子へ伝わる際、優性(顕性)の形質のみが現れる法則はどれか。', NULL, '["分離の法則","独立の法則","優性の法則","連鎖の法則","突然変異の法則"]', 2, '["対立する2つの形質のうち、雑種第一代(F1)には優性(顕性)の形質だけが現れることを優性の法則という。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '光合成が行われる細胞小器官はどれか。', NULL, '["核","ミトコンドリア","葉緑体","液胞","リボソーム"]', 2, '["葉緑体には光合成色素であるクロロフィルが含まれており、光エネルギーを利用して二酸化炭素と水からデンプンと酸素をつくる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, 'ヒトの神経系のうち、意思とは無関係に内臓の働きなどを調節する神経を何というか。', NULL, '["運動神経","感覚神経","自律神経","中枢神経","末梢神経のうち体性神経"]', 2, '["自律神経は交感神経と副交感神経からなり、意思とは無関係に心臓の拍動や消化などの働きを調節する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '生態系における生産者の役割を果たす生物はどれか。', NULL, '["肉食動物","草食動物","植物などの光合成生物","分解者である菌類・細菌類","雑食動物"]', 2, '["生産者は光合成によって無機物から有機物をつくり出す植物やプランクトンなどを指す。動物は消費者、菌類・細菌類は分解者にあたる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, 'DNAの構造として正しいものはどれか。', NULL, '["一本のらせん構造","二重らせん構造","三重らせん構造","環状の単鎖構造のみ","平面的な格子構造"]', 1, '["DNAは2本のヌクレオチド鎖が塩基の対によって結びつき、らせん状にねじれた二重らせん構造をとる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, 'ヒトの呼吸において、酸素と二酸化炭素のガス交換が行われる場所はどれか。', NULL, '["気管","気管支","肺胞","横隔膜","食道"]', 2, '["肺の中にある無数の小さな袋状の構造である肺胞で、毛細血管との間で酸素と二酸化炭素のガス交換が行われる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・生物）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '地震の規模の大きさを表す指標はどれか。', NULL, '["震度","マグニチュード","気圧","湿度","風速"]', 1, '["マグニチュードは地震そのもののエネルギーの大きさを表す指標。震度は各観測地点での揺れの強さを表す。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '堆積岩のうち、生物の遺骸(貝殻やサンゴなど)が固まってできる岩石はどれか。', NULL, '["花こう岩","玄武岩","石灰岩","安山岩","流紋岩"]', 2, '["石灰岩は主にサンゴや貝殻などの生物の遺骸(炭酸カルシウム)が海底に堆積して固まってできた堆積岩である。花こう岩・玄武岩・安山岩・流紋岩は火成岩。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '太陽系の惑星のうち、地球のすぐ内側の軌道を公転している惑星はどれか。', NULL, '["火星","木星","金星","水星","土星"]', 2, '["太陽から近い順に水星・金星・地球・火星と並んでおり、地球のすぐ内側を公転しているのは金星である。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '日本付近で夏に発達しやすく、蒸し暑い晴天をもたらす気団はどれか。', NULL, '["シベリア気団","オホーツク海気団","小笠原気団","揚子江気団","北極気団"]', 2, '["小笠原気団は高温多湿な気団で、夏に勢力を強め日本付近を覆うことで蒸し暑い晴天をもたらす。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '地層が堆積した年代の新旧を判断する際の基本原則で、「下にある地層ほど古い」とする考え方を何というか。', NULL, '["地層累重の法則","示準化石の法則","整合の法則","風化の法則","堆積作用の法則"]', 0, '["地層が乱されていない限り、下の層ほど先に堆積した古い地層であるという考え方を地層累重の法則という。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '月が満ち欠けする理由として正しいものはどれか。', NULL, '["月自体が発光量を変化させているから","地球の影が月にかかる角度が変わるから","太陽・地球・月の位置関係により、太陽光の当たる部分の見え方が変わるから","月の自転周期が変化するから","大気による光の屈折のため"]', 2, '["月は自ら光を発しておらず、太陽光を反射して光って見える。地球から見たときの太陽・地球・月の位置関係によって、光が当たって見える部分の形が変化するため満ち欠けが起こる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '偏西風の影響を強く受ける日本の天気の特徴として正しいものはどれか。', NULL, '["天気は東から西へ変化することが多い","天気は西から東へ変化することが多い","一年中天気はほとんど変化しない","偏西風は日本付近には吹かない","天気の変化は南北方向にのみ起こる"]', 1, '["日本付近の上空には西から東へ吹く偏西風が吹いており、これに乗って移動性高気圧や低気圧が西から東へ移動するため、天気も西から東へ変化することが多い。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '火山岩のうち、マグマが地表や地表付近で急速に冷え固まってできた岩石の組織を何というか。', NULL, '["等粒状組織","斑状組織","堆積組織","変成組織","片状組織"]', 1, '["マグマが地表付近で急速に冷え固まると、大きな結晶(斑晶)が細かい粒(石基)の中に散らばった斑状組織になる。ゆっくり冷え固まると等粒状組織(深成岩)になる。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, '台風の中心付近に見られる、雲がほとんどなく風の弱い部分を何というか。', NULL, '["前線","台風の目","積乱雲","気圧の谷","収束帯"]', 1, '["台風の中心部分には「台風の目」と呼ばれる、下降気流によって雲が少なく風も比較的弱い領域が存在する。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note) VALUES ('scoa_common_sense', '理科', NULL, 'プレートテクトニクスにおいて、プレートどうしがすれ違うように動く境界を何というか。', NULL, '["発散型境界","収束型境界","トランスフォーム断層(すれ違い境界)","沈み込み境界","中央海嶺境界"]', 2, '["プレートが互いに水平方向にすれ違うように動く境界をトランスフォーム断層(すれ違い境界)という。サンアンドレアス断層が代表例。"]', 3, 'published', 'ユーザー提供のオリジナル問題（SCOA常識分野: 理科・地学）');
